def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Extend rays from the colored marker in four directions, painting over 0s only;
    # 8 cells are obstacles, with the patterned rows acting as barriers/openings.
    from collections import deque
    q=deque((r,c) for r in range(h) for c in range(w) if grid[r][c]==2)
    seen=set(q)
    while q:
        r,c=q.popleft()
        for dr in (-1,0,1):
          for dc in (-1,0,1):
            if dr==dc==0: continue
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r,c in seen: out[r][c]=2
    return out

